insert into projects (id, slug, title, category, location, description, services, year, cover_path, images, before_path, after_path, featured, sort_order, created_at) values
  ('p1', 'modern-apartment-interior', '{"en":"Modern Apartment Interior","fr":"Intérieur d''appartement moderne","ar":"شقة داخلية عصرية"}'::jsonb, 'residential', '{"en":"Sebdou","fr":"Sebdou","ar":"سبدو"}'::jsonb, '{"en":"Full interior renovation of a 3-bedroom apartment including false ceilings, partition walls, interior painting and custom drywall features.","fr":"Rénovation intérieure complète d''un appartement 3 chambres avec plafonds suspendus, cloisons, peinture et éléments en placo personnalisés.","ar":"ترميم داخلي كامل لشقة مكونة من 3 غرف نوم بما في ذلك الأسقف المعلقة، القواطع، الطلاء الداخلي وتصاميم جبس بورد مخصصة."}'::jsonb, array['drywall','ceilings','partitions','painting','renovation']::text[], 2025, 'dryceiling/dryceiling-01.jpg', array['dryceiling/dryceiling-02.jpg','dryceiling/dryceiling-03.jpg','dryceiling/dryceiling-04.jpg','dryceiling/dryceiling-05.jpg','dryceiling/dryceiling-06.jpg','dryceiling/dryceiling-07.jpg','dryceiling/dryceiling-08.jpg','dryceiling/dryceiling-09.jpg','dryceiling/dryceiling-10.jpg','dryceiling/dryceiling-11.jpg','dryceiling/dryceiling-12.jpg','dryceiling/dryceiling-13.jpg','dryceiling/dryceiling-14.jpg','dryceiling/dryceiling-15.jpg','dryceiling/dryceiling-16.jpg','dryceiling/dryceiling-17.jpg','dryceiling/dryceiling-18.jpg']::text[], null, null, true, 0, '2025-01-15'),
