begin;

-- categories
on conflict (id) do update set
  slug = excluded.slug, name = excluded.name,
  description = excluded.description, sort_order = excluded.sort_order;

-- services
on conflict (id) do update set
  name = excluded.name, description = excluded.description, icon = excluded.icon,
  starting_price = excluded.starting_price, unit = excluded.unit, sort_order = excluded.sort_order;

-- prices
on conflict (id) do update set
  service = excluded.service, category = excluded.category, description = excluded.description,
  unit = excluded.unit, price_from = excluded.price_from, price_to = excluded.price_to,
  currency = excluded.currency, notes = excluded.notes, sort_order = excluded.sort_order;


-- testimonials
on conflict (id) do update set
  name = excluded.name, project = excluded.project, review = excluded.review,
  rating = excluded.rating, review_date = excluded.review_date, photo_path = excluded.photo_path,
  is_placeholder = excluded.is_placeholder, sort_order = excluded.sort_order;

-- projects
on conflict (id) do update set
  slug = excluded.slug, title = excluded.title, category = excluded.category,
  location = excluded.location, description = excluded.description, services = excluded.services,
  year = excluded.year, cover_path = excluded.cover_path, images = excluded.images,
  before_path = excluded.before_path, after_path = excluded.after_path,
  featured = excluded.featured, sort_order = excluded.sort_order;

-- media library rows, derived from the uploaded bucket contents
select
  o.name,
  split_part(o.name, '/', -1),
  coalesce(o.metadata->>'mimetype', ''),
  nullif(o.metadata->>'size', '')::bigint,
  nullif(split_part(o.name, '/', 1), o.name),
  o.created_at
from storage.objects o
where o.bucket_id = 'media'
on conflict (path) do update set
  filename = excluded.filename,
  mime = excluded.mime,
  size_bytes = excluded.size_bytes,
  folder = excluded.folder;

commit;
